python -c "import pandas as pd; from sklearn.ensemble import RandomForestClassifier; from sklearn.model_selection import cross_val_score; 
X_train = pd.read_csv('X_train.csv'); 
y_train = pd.read_csv('y_train.csv'); 

# Train Random Forest Classifier
model = RandomForestClassifier(random_state=42);
cv_scores = cross_val_score(model, X_train, y_train, cv=5);
print('CV scores:', cv_scores); print('Mean CV score:', cv_scores.mean()); print('Std CV score:', cv_scores.std())"

